function buttonInstance(button, label, name) {
  const inst = button.component.createInstance();
  inst.name = name;
  inst.setProperties({ [button.labelKey]: label });
  return inst;
}

function taskInstance(task, title, meta, state, name) {
  const inst = task.component.createInstance();
  inst.name = name;
  inst.setProperties({
    [task.keys.title]: title,
    [task.keys.meta]: meta,
    [task.keys.state]: state
  });
  return inst;
}

function metricInstance(metric, label, value, name) {
  const inst = metric.component.createInstance();
  inst.name = name;
  inst.setProperties({
    [metric.keys.label]: label,
    [metric.keys.value]: value
  });
  return inst;
}

function makeGridSvg(w, h) {
  let lines = "";
  for (let x = 0; x <= w; x += 80) {
    lines += `<line x1="${x}" y1="0" x2="${x}" y2="${h}" />`;
  }
  for (let y = 0; y <= h; y += 80) {
    lines += `<line x1="0" y1="${y}" x2="${w}" y2="${y}" />`;
  }
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg"><g stroke="#9CB7FF" stroke-opacity="0.035" stroke-width="1">${lines}</g></svg>`;
}

