function makeRingSvg(progress, statusColor = C.cyan) {
  const r = 72;
  const circumference = 2 * Math.PI * r;
  const dash = circumference * progress;
  return `
    <svg width="180" height="180" viewBox="0 0 180 180" fill="none" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="ring" x1="24" y1="18" x2="158" y2="164" gradientUnits="userSpaceOnUse">
          <stop stop-color="${C.indigo}"/>
          <stop offset="0.52" stop-color="${statusColor}"/>
          <stop offset="1" stop-color="${C.pink}"/>
        </linearGradient>
      </defs>
      <circle cx="90" cy="90" r="72" stroke="#262B3E" stroke-width="10"/>
      <circle cx="90" cy="90" r="72" stroke="url(#ring)" stroke-width="10" stroke-linecap="round"
        stroke-dasharray="${dash.toFixed(2)} ${circumference.toFixed(2)}"
        transform="rotate(-90 90 90)"/>
      <circle cx="90" cy="18" r="3.5" fill="${C.text}" opacity="0.95"/>
    </svg>
  `;
}

function makeSparkSvg(paused = false) {
  const values = [24, 31, 29, 39, 36, 49, 44, 55, 51, 60, 57, 62, 55, 58, 63, 61, 67, 62, 65, 64, 70, 67, 73, 69];
  const w = 576;
  const h = 60;
  const max = 80;
  let points = [];
  values.forEach((v, i) => {
    const x = (w * i) / (values.length - 1);
    const y = h - (v / max) * h;
    points.push([x, y]);
  });
  const line = points.map((p, i) => `${i === 0 ? "M" : "L"} ${p[0].toFixed(2)} ${p[1].toFixed(2)}`).join(" ");
  const area = `${line} L ${w} ${h} L 0 ${h} Z`;
  const stroke = paused ? "#596077" : `url(#spark)`;
  return `
    <svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" fill="none" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="spark" x1="0" y1="20" x2="${w}" y2="20" gradientUnits="userSpaceOnUse">
          <stop stop-color="${C.indigo}" stop-opacity="0.45"/>
          <stop offset="0.45" stop-color="${C.cyan}"/>
          <stop offset="1" stop-color="${C.pink}"/>
        </linearGradient>
        <linearGradient id="fill" x1="0" y1="0" x2="0" y2="${h}" gradientUnits="userSpaceOnUse">
          <stop stop-color="${C.cyan}" stop-opacity="${paused ? 0.03 : 0.18}"/>
          <stop offset="1" stop-color="${C.cyan}" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <path d="${area}" fill="url(#fill)"/>
      <path d="${line}" stroke="${stroke}" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>
      <circle cx="${w - 4}" cy="${points[points.length - 1][1].toFixed(2)}" r="4" fill="${paused ? "#596077" : C.cyan}"/>
    </svg>
  `;
}

