  laneBlock.layoutMode = "VERTICAL";
  laneBlock.primaryAxisSizingMode = "FIXED";
  laneBlock.counterAxisSizingMode = "FIXED";
  laneBlock.itemSpacing = 7;
  content.appendChild(laneBlock);
  const laneHeader = figma.createFrame();
  laneHeader.name = "Task / Lane Header";
  laneHeader.resize(600, 15);
  laneHeader.fills = [];
  laneHeader.layoutMode = "HORIZONTAL";
  laneHeader.primaryAxisSizingMode = "FIXED";
  laneHeader.counterAxisSizingMode = "FIXED";
  laneHeader.counterAxisAlignItems = "CENTER";
  laneBlock.appendChild(laneHeader);
  addText(laneHeader, "Task / Lane Label", paused ? "CHAKRA LANES · 0 / 16 ACTIVE" : "CHAKRA LANES · 12 / 16 ACTIVE", "qd/label/caps", paused ? "state/warning" : "text/muted");
  addSpacer(laneHeader, "Task / Lane Spacer");
  addText(laneHeader, "Task / Lane Hint", "DYNAMIC CHUNK QUEUE", "qd/label/caps", "brand/crimson");
  const laneRow = figma.createFrame();
  laneRow.name = "Task / Lane Row";
  laneRow.resize(600, 20);
  laneRow.fills = [];
  laneRow.layoutMode = "HORIZONTAL";
  laneRow.primaryAxisSizingMode = "FIXED";
  laneRow.counterAxisSizingMode = "FIXED";
  laneRow.counterAxisAlignItems = "MAX";
  laneRow.itemSpacing = 5;
  laneBlock.appendChild(laneRow);
  const heights = [12, 20, 16, 23, 14, 25, 13, 21, 18, 24, 12, 20, 15, 22, 13, 18];
  for (let i = 0; i < 16; i++) {
    const lane = comps.lane.createInstance();
    lane.name = `Task / Lane ${String(i + 1).padStart(2, "0")}`;
    laneRow.appendChild(lane);
    lane.resize(7, paused || i >= 12 ? 5 : heights[i]);
    if (paused || i >= 12) lane.fills = [solid(paused ? "#343A4D" : "#343D56")];
  }

  const actions = figma.createFrame();
  actions.name = "Task / Actions";
  actions.resize(600, 44);
  actions.fills = [];
