async function build() {
  figma.notify("QuickDL: 正在生成佐助主题原型…");
  currentStep = "加载字体";
  await loadFonts();

  currentStep = "清理旧画板";
  cleanupGenerated();
  figma.currentPage.name = "QuickDL · 佐助原型";

  currentStep = "载入佐助本地图片";
  try {
    const bytes = figma.base64Decode
      ? figma.base64Decode(ART_BASE64)
      : Uint8Array.from(atob(ART_BASE64), c => c.charCodeAt(0));
    const image = figma.createImage(bytes);
    artHash = image.hash;
  } catch (err) {
    artHash = null;
    warnings.push(`本地角色图载入失败：${err.message}`);
  }

  currentStep = "创建主题变量";
  try {
    await ensureTokens();
  } catch (err) {
    tokens = {};
    warnings.push(`主题变量不可用，已回退为固定色值：${err.message}`);
  }

  currentStep = "创建文字样式";
  try {
    await ensureTextStyles();
  } catch (err) {
    warnings.push(`文字样式不可用，已回退为手动字体：${err.message}`);
  }

  currentStep = "创建效果样式";
  try {
    await ensureEffectStyles();
  } catch (err) {
    effectStyles = {};
    warnings.push(`效果样式不可用，已跳过阴影与发光：${err.message}`);
  }

  currentStep = "创建可复用组件";
  buildComponents();

  currentStep = "构建下载主界面";
  const main = buildScreen("downloading", 0);

  currentStep = "构建暂停状态";
  const paused = buildScreen("paused", 1520);

  currentStep = "构建新建下载弹窗";
  const modalParts = buildModal(main);

  const find = (root, name) => root.findOne(n => n.name === name);
  const newDownload = find(main, "page/newDownload");
  const pause = find(main, "page/pause");
  const resume = find(paused, "page/resume");
  const modalCancel = modalParts.cancel;
  const modalStart = modalParts.start;
  const modalClose = modalParts.close;

  currentStep = "设置原型交互";
  try {
    if (newDownload) setReaction(newDownload, modalParts.modal, "dissolve");
    if (pause) setReaction(pause, paused, "smart");
    if (resume) setReaction(resume, main, "smart");
    if (modalCancel) setReaction(modalCancel, main, "dissolve");
    if (modalStart) setReaction(modalStart, main, "dissolve");
    if (modalClose) setReaction(modalClose, main, "dissolve");
  } catch (err) {
    warnings.push(`原型跳转未完全设置：${err.message}`);
  }

  figma.currentPage.selection = [main];
  figma.viewport.scrollAndZoomIntoView([main]);
  const warningSuffix = warnings.length ? `；回退项 ${warnings.length} 个` : "";
  figma.closePlugin(`QuickDL 原型已生成：主界面、暂停状态、新建下载弹窗${warningSuffix}。`);
}

build().catch(err => {
  figma.closePlugin(`QuickDL 生成失败【${currentStep}】：${err.message}`);
});
